DValue doc_capy_signature_lines(String page)
{
	DValue lines;
	for(const auto& entry : doc_capy_signatures)
	{
		if(entry.page == std::string_view(page))
			lines.push_back(String(entry.declaration));
		else if(lines.size() > 0)
			break;
	}
	return(lines);
}
